from pathlib import Path
import json
folder=Path(__file__).parent;meta=json.loads((folder/'books/summary.json').read_text());catalogue=[]
kindNames={4:'move',5:'basic attack',6:'cast ability',9:'next-round priority',11:'start recall',12:'start tribute',13:'buy item shards',14:'place ward',16:'cancel channel',20:'place altar lock',21:'start teleport crystal',25:'sell item',30:'buy consumable'}
names=['Ryth','Vesper','Vendetta','Cassi','Issac','Stellar','Prism','Marcella','Willow','Ren','Varg','Tavi','Heart of Ruin']
for m in meta:
 d=json.loads((folder/'books'/m['file']).read_text());us=d['team'];owncaptures=[c for c in d['captures'] if c['team']==us];ownDeaths=[c for c in d['deaths'] if c['team']==us];enemyDeaths=[c for c in d['deaths'] if c['team']!=us];totals={t:sum(c['gems'] for c in owncaptures if c['t']==t) for t in {c['t'] for c in owncaptures}};collector=max(totals,key=totals.get) if totals else None
 first=owncaptures[0] if owncaptures else None;lastBank=[b for b in d['banking'] if b['team']==us][-1:] or []
 segments=[]
 def segment(kind,start,end,why,evidence,uncertainty):
  acts=[{'round':a['r'],'champion':names[a['t']],'kind':a['k'],'action':kindNames.get(a['k'],'unknown'),'destination':[a['x'],a['y']],'slotOrItem':a['s'],'value':a['v']} for a in d['actions'] if start<=a['r']<=end]
  segments.append({'kind':kind,'roundStart':start,'roundEnd':end,'whyChosen':why,'evidence':evidence,'uncertainty':uncertainty,'actionCount':len(acts),'sampleActions':acts[:24],'completeActionsFile':'../books/'+m['file']})
 if first:segment('opening route and first reward',1,first['r'],f"Reach the first observed reward at round {first['r']}; preserve the route and schedule that supplied {names[first['t']]} with {first['gems']} gems and {first['gold']} gold.",{'firstCapture':first,'earlyCaptures':owncaptures[:8]},'A successful observed opening; individual moves have not been ablated.')
 if collector is not None:segment('resource allocation and scaling',1,min(m['rounds'],400),f"Preserve the reward allocation used by this win. {names[collector]} was the largest camp-gem collector ({totals[collector]} gems over the whole game).",{'campGemsByChampion':{names[k]:v for k,v in totals.items()},'earlyBuys':d['buys'][:20]},'Collector totals are descriptive; do not infer an optimal universal carry from one win.')
 for n,kill in enumerate(enemyDeaths[:3]):
  segment('Fish combat loss '+str(n+1),max(1,kill['r']-8),kill['r'],f"Preserve the movement, cast and attack ordering preceding Fish's {names[kill['t']]} death at round {kill['r']}. This is a concrete candidate counter to its observed approach.",{'fishDeath':kill,'casts': [c for c in d['casts'] if kill['r']-8<=c['r']<=kill['r']]},'No ablation separates target choice, equipment, ally timing and positioning; replay reproduction tests the combined sequence.')
 bankStart=max(1,m['rounds']-max(30,(m['score']+9)//10))
 segment('convert advantage into banked score',bankStart,m['rounds'],'Preserve the final altar approach, denial consumables and tribute scheduling that turned the collected resources into this recorded victory.',{'lastBankEvents':[b for b in d['banking'] if b['team']==us][-8:],'sourceScore':m['score'],'fishScore':m['enemyScore'],'finishRound':m['rounds']},'Channel success depends on current Fish pressure and locks; this win must be reproduced live.')
 catalogue.append({'case':m['map']+'/'+m['side'],'map':m['map'],'side':m['side'],'sourceReplay':m['source'],'sourceTeam':m.get('team',d.get('sourceTeam','developer team (cached)')),'sourceTime':m['at'],'patch':d['patchId'],'draft':d['draft'],'fingerprint':{'width':m['w'],'height':m['h'],'groups':m['groups'],'ownSpawn':m['spawn']},'selectionReason':d['selectionReason'],'sourceResult':{'score':m['score'],'fishScore':m['enemyScore'],'rounds':m['rounds']},'alternatives':d['alternatives'],'observedFishPattern':{'draft':d['oppDraft'],'deaths':enemyDeaths[:12],'bankEvents':[b for b in d['banking'] if b['team']!=us][:12]},'ourDeaths':ownDeaths[:12],'segments':segments,'requiredConditions':['Same static map and side.','Same reference draft and draft order.','Fish behaviour must remain sufficiently close to its reference trajectory.','All live actions remain subject to legal action availability and personal vision.'],'failureTriggers':['Fish changes draft, opening, scheduling, purchases or routing.','A movement, cast or channel diverges and shifts later contacts.','A map revision changes geometry or camp composition.'],'fallback':'v77 reactive controller for an unsupported case or after the recorded horizon; not a proven Fish counter.','status':'reference selected; new live validation pending'})
(folder/'catalogue').mkdir(exist_ok=True);(folder/'catalogue/counterplay.json').write_text(json.dumps(catalogue,indent=2));lines=['# Counterplay catalogue','',f'{len(catalogue)} exact map/side cases. Each selection is a hypothesis until a new live Fish challenge verifies it. Full action lists are in `../books/` and the machine-readable explanations are in `counterplay.json`.','']
for c in catalogue:
 lines+=['## '+c['case'],'',f"Source **{c['sourceTeam']}**, {c['sourceTime']}, replay `{c['sourceReplay']}`. Recorded win **{c['sourceResult']['score']}–{c['sourceResult']['fishScore']}**, round {c['sourceResult']['rounds']}.",'','Draft: '+', '.join(c['draft'])+'.','',*['- '+r for r in c['selectionReason']],'']
 for s in c['segments']:lines += [f"**Rounds {s['roundStart']}–{s['roundEnd']}: {s['kind']}.** {s['whyChosen']} {s['uncertainty']}",'']
(folder/'catalogue/README.md').write_text('\n'.join(lines)+'\n');print('Catalogued',len(catalogue),'cases with',sum(len(c['segments']) for c in catalogue),'explained move sequences')
